"""Build fork release archives and the matching Homebrew formula."""

import argparse
import gzip
import hashlib
from pathlib import Path
import re
import tarfile
import tomllib


ROOT = Path(__file__).resolve().parents[2]
REPOSITORY = "Timo-In/serie"
TARGETS = {
    "macos": ("aarch64-apple-darwin", "x86_64-apple-darwin"),
    "linux": ("aarch64-unknown-linux-gnu", "x86_64-unknown-linux-gnu"),
}
ALL_TARGETS = tuple(target for targets in TARGETS.values() for target in targets)


def release_version(root=ROOT):
    with (root / "Cargo.toml").open("rb") as stream:
        version = tomllib.load(stream)["package"]["version"]
    if not re.fullmatch(r"\d+\.\d+\.\d+-timo(?:\.[1-9]\d*)?", version):
        raise ValueError(
            f"Expected a fork version such as 0.10.1-timo or 0.10.1-timo.1, got {version!r}"
        )
    return version


def validate_tag(tag, version):
    if tag != f"v{version}":
        raise ValueError(f"Tag {tag!r} must match Cargo.toml version v{version}")


def archive_name(version, target):
    if target not in ALL_TARGETS:
        raise ValueError(f"Unsupported target: {target}")
    return f"serie-timo-{version}-{target}.tar.gz"


def create_archive(root, version, target, output):
    name = archive_name(version, target)
    binary = root / "target" / target / "release" / "serie"
    if not binary.is_file():
        raise ValueError(f"Release binary is missing: {binary}")
    output.mkdir(parents=True, exist_ok=True)
    destination = output / name
    with destination.open("wb") as stream:
        # Stable archive metadata makes retries reproducible for the same inputs.
        with gzip.GzipFile(filename="", fileobj=stream, mode="wb", mtime=0) as compressed:
            with tarfile.open(fileobj=compressed, mode="w") as archive:
                for source, mode in [(binary, 0o755), (root / "LICENSE", 0o644), (root / "README.md", 0o644)]:
                    info = archive.gettarinfo(str(source), arcname=source.name)
                    info.uid = info.gid = info.mtime = 0
                    info.uname = info.gname = ""
                    info.mode = mode
                    with source.open("rb") as content:
                        archive.addfile(info, content)
    return destination


def render_formula(version, checksums):
    lines = [
        "# typed: false",
        "# frozen_string_literal: true",
        "",
        "# Generated by the Serie Timo release workflow. DO NOT EDIT.",
        "class SerieTimo < Formula",
        '  desc "Git commit graph with Timo\'s file tree and diff viewer"',
        f'  homepage "https://github.com/{REPOSITORY}"',
        f'  version "{version}"',
        '  license "MIT"',
        "",
        '  depends_on "git"',
    ]
    for system, targets in TARGETS.items():
        lines.extend(["", f"  on_{system} do", "    if Hardware::CPU.arm?"])
        for index, target in enumerate(targets):
            if index:
                lines.append("    else")
            name = archive_name(version, target)
            lines.extend([
                f'      url "https://github.com/{REPOSITORY}/releases/download/v{version}/{name}"',
                f'      sha256 "{checksums[name]}"',
            ])
        lines.extend(["    end", "  end"])
    lines.extend([
        "",
        '  conflicts_with "serie", because: "both install a serie binary"',
        "",
        "  def install",
        '    bin.install "serie"',
        "  end",
        "",
        "  test do",
        '    assert_match version.to_s, shell_output("#{bin}/serie --version")',
        "  end",
        "end",
        "",
    ])
    return "\n".join(lines)


def generate_formula(version, artifacts, output):
    checksums = {}
    for target in ALL_TARGETS:
        name = archive_name(version, target)
        archive = artifacts / name
        if not archive.is_file():
            raise ValueError(f"Missing release archive: {name}")
        with archive.open("rb") as stream:
            checksums[name] = hashlib.file_digest(stream, "sha256").hexdigest()
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render_formula(version, checksums), encoding="utf-8")
    (artifacts / "SHA256SUMS").write_text(
        "".join(f"{checksums[name]}  {name}\n" for name in sorted(checksums)), encoding="utf-8"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    validate = commands.add_parser("validate-tag")
    validate.add_argument("tag")
    archive = commands.add_parser("archive")
    archive.add_argument("--target", choices=ALL_TARGETS, required=True)
    archive.add_argument("--output", type=Path, required=True)
    formula = commands.add_parser("formula")
    formula.add_argument("--artifacts", type=Path, required=True)
    formula.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        version = release_version()
        if args.command == "validate-tag":
            validate_tag(args.tag, version)
            print(f"version={version}")
        elif args.command == "archive":
            print(create_archive(ROOT, version, args.target, args.output))
        else:
            generate_formula(version, args.artifacts, args.output)
    except (ValueError, OSError) as error:
        parser.exit(1, f"{error}\n")


if __name__ == "__main__":
    main()
